export function minimumWindowSubstring(text        , required        )         {
if(!required)return '';const need=new Map               ();for(const c of required)need.set(c,(need.get(c)??0)+1);let remaining=required.length,l=0,start=0,length=Infinity;for(let r=0;r<text.length;r++){const c=text[r];if((need.get(c)??0)>0)remaining--;need.set(c,(need.get(c)??0)-1);while(remaining===0){if(r-l+1<length){start=l;length=r-l+1;}const left=text[l++];need.set(left,(need.get(left)??0)+1);if(need.get(left) >0)remaining++;}}return length===Infinity?'':text.slice(start,start+length);
}

